import {materials} from './materials.js';
import {InkLayer} from './ink.js';
const $=s=>document.querySelector(s);
const levels=['Year 4','Year 5','Year 6','Form 1','Form 2','Form 3','Form 4','Form 5'];
const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
const subjects={BM:'Bahasa Melayu',BI:'Bahasa Inggeris',Science:'Science'};
let selection={level:null,subject:null,month:null};
let current=null,doc=null,loadingTask=null,renderTask=null,page=1,zoom=1,epoch=0,renderEpoch=0,deckTimer=null,renderQueue=Promise.resolve();
const layers=new Map();let active=null;
const settings={tool:'interact',color:'#ba315b',size:4,finger:false};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function matching(filter){return materials.filter(m=>Object.entries(filter).every(([k,v])=>v===null||m[k]===v))}
function countLabel(n){return n?`${n} material${n===1?'':'s'}`:'Ready for lessons'}
function renderLibrary(){const s=selection;$('#breadcrumbs').replaceChildren();const crumb=(label,action)=>{const b=document.createElement('button');b.textContent=label;b.onclick=action;$('#breadcrumbs').append(b);};crumb('All levels',()=>{selection={level:null,subject:null,month:null};renderLibrary()});if(s.level)crumb(s.level,()=>{selection={level:s.level,subject:null,month:null};renderLibrary()});if(s.subject)crumb(s.subject,()=>{selection.month=null;renderLibrary()});if(s.month)crumb(months[s.month-1],()=>{});
 const box=$('#choices');box.className='';
 if(!s.level){$('#sectionTitle').textContent='Choose a level';$('#sectionMeta').textContent='08 LEVELS';box.className='level-grid';box.innerHTML=levels.map(level=>{let n=matching({level}).length;return `<button class="level-card ${n?'ready':''}" data-level="${level}"><span class="tag">${level.startsWith('Year')?'PRIMARY':'SECONDARY'}</span><strong>${level}</strong><span class="card-bottom">${countLabel(n)} <span class="arrow">↗</span></span></button>`}).join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{selection.level=b.dataset.level;renderLibrary()});}
 else if(!s.subject){$('#sectionTitle').textContent=`${s.level} · Choose a subject`;$('#sectionMeta').textContent=s.level.startsWith('Year')?'PRIMARY':'03 SUBJECTS';if(s.level.startsWith('Year')){box.innerHTML='<div class="empty"><h3>A little space for what’s next.</h3><p>Primary subjects and materials haven’t been added yet.</p></div>';return}box.className='subject-grid';box.innerHTML=Object.entries(subjects).map(([key,name])=>{let n=matching({level:s.level,subject:key}).length;return `<button class="level-card ${n?'ready':''}" data-subject="${key}"><span class="tag">${escape(name)}</span><strong>${key}</strong><span class="card-bottom">${countLabel(n)} <span class="arrow">↗</span></span></button>`}).join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{selection.subject=b.dataset.subject;renderLibrary()});}
 else if(!s.month){$('#sectionTitle').textContent='Choose a month';$('#sectionMeta').textContent='12 MONTHS';box.className='month-grid';box.innerHTML=months.map((name,i)=>{let n=matching({...s,month:i+1}).length;return `<button class="month-card ${n?'ready':''}" data-month="${i+1}"><span class="month-no">${String(i+1).padStart(2,'0')}</span><span><strong>${name}</strong><small>${n?countLabel(n):'No materials yet'}</small></span></button>`}).join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{selection.month=+b.dataset.month;renderLibrary()});}
 else{const list=matching(s);$('#sectionTitle').textContent=`${months[s.month-1]} lessons`;$('#sectionMeta').textContent=`${list.length} MATERIAL${list.length===1?'':'S'}`;box.className='material-list';box.innerHTML=list.length?list.map(m=>`<button class="material-card" data-material="${m.id}"><span class="file-icon ${m.type}">${m.type.toUpperCase()}</span><span class="material-info"><strong>${escape(m.title)}</strong><small>${escape(m.detail||'PDF booklet · Write and highlight on every page')}</small></span><span class="open-label">Open lesson ↗</span></button>`).join(''):'<div class="empty"><h3>A fresh page awaits.</h3><p>No materials for this month yet. Try November.</p></div>';box.querySelectorAll('button').forEach(b=>b.onclick=()=>openMaterial(materials.find(m=>m.id===b.dataset.material)));}}
$('#loginForm').onsubmit=e=>{e.preventDefault();if($('#password').value==='iamtheonlyadmin'){$('#login').hidden=true;$('#library').hidden=false;$('#password').value='';$('#loginError').textContent='';renderLibrary();$('#home').focus()}else{$('#loginError').textContent='That password didn’t match. Please try again.';$('#password').focus()}};
$('#showPassword').onclick=()=>{const p=$('#password');p.type=p.type==='password'?'text':'password';$('#showPassword').textContent=p.type==='password'?'Show':'Hide';$('#showPassword').setAttribute('aria-label',p.type==='password'?'Show password':'Hide password')};
$('#lock').onclick=()=>{$('#library').hidden=true;$('#login').hidden=false;$('#password').focus()};
$('#home').onclick=e=>{e.preventDefault();selection={level:null,subject:null,month:null};renderLibrary()};
function setTool(tool){settings.tool=tool;document.querySelectorAll('[data-tool]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.tool===tool));for(const layer of layers.values())layer.update();$('#toolHint').textContent=tool==='interact'?'Interact with the lesson. Choose Pen or Highlight to annotate.':`${tool==='erase'?'Erase strokes':tool==='pen'?'Write':'Highlight'} with Apple Pencil${settings.finger?' or your finger':''}. Switch to Interact to scroll or use lesson buttons.`;}
for(const b of document.querySelectorAll('[data-tool]'))b.onclick=()=>setTool(b.dataset.tool);
$('#ink').oninput=e=>{settings.color=e.target.value};$('#penSize').onchange=e=>{settings.size=+e.target.value};$('#fingerDraw').onchange=e=>{settings.finger=e.target.checked;setTool(settings.tool)};
$('#undo').onclick=()=>active?.undo();$('#clearInk').onclick=()=>active?.clear();
function updateUndo(){$('#undo').disabled=!active?.history.length;$('#clearInk').disabled=!active?.strokes.length}
function attach(target,key){let layer=layers.get(key);if(!layer||!layer.svg.isConnected){const old=layer;layer=new InkLayer(target,()=>settings,updateUndo);if(old){layer.strokes=old.strokes;layer.history=old.history;old.destroy();layer.draw()}layers.set(key,layer)}active=layer;updateUndo();return layer;}
function status(message){$('#loadStatus').textContent=message;$('#loadStatus').hidden=!message}
async function openMaterial(m){closeMaterial(false);current=m;const token=++epoch;$('#viewer').hidden=false;$('#library').hidden=true;$('#materialTitle').textContent=m.title;$('#materialMeta').textContent=`${m.level} / ${m.subject} / November · ${m.type.toUpperCase()}`;status('Opening your lesson…');setTool('interact');$('#closeViewer').focus();
 if(m.type==='html'){$('#deck').hidden=false;$('#deck').onload=()=>{if(token!==epoch)return;const frame=$('#deck');try{const d=frame.contentDocument;if(!d?.querySelector('script'))throw Error('Lesson missing');status('');syncDeck();deckTimer=setInterval(syncDeck,120)}catch{status('This lesson could not open. Close it and try again.')}};$('#deck').src='assets/materials/'+m.file;}
 else{$('#pdfControls').hidden=false;$('#pdfScroll').hidden=false;try{const pdfjs=await import('./assets/vendor/pdf.mjs');if(token!==epoch)return;pdfjs.GlobalWorkerOptions.workerSrc=new URL('./assets/vendor/pdf.worker.mjs',import.meta.url).href;loadingTask=pdfjs.getDocument({url:'assets/materials/'+m.file,cMapUrl:'assets/vendor/cmaps/',cMapPacked:true,standardFontDataUrl:'assets/vendor/standard_fonts/'});const loaded=await loadingTask.promise;if(token!==epoch){await loaded.destroy();return}doc=loaded;$('#pageTotal').textContent=`of ${doc.numPages}`;$('#pageNumber').max=doc.numPages;await renderPDF()}catch(e){if(token===epoch){status('Unable to open this PDF. Please close it and try again.');console.error(e)}}}}
function syncDeck(){if(current?.type!=='html')return;try{const d=$('#deck').contentDocument;let target,key;if(d.querySelector('#slide')){target=d.querySelector('#slide');key='science-'+d.querySelector('#position')?.textContent}else{const slide=d.querySelector('.slide.active');target=slide?.querySelector('.content');key='english-'+[...d.querySelectorAll('.slide')].indexOf(slide)}if(target)attach(target,key)}catch{}}
function renderPDF(){const job=++renderEpoch;renderTask?.cancel();renderQueue=renderQueue.catch(()=>{}).then(async()=>{if(!doc||job!==renderEpoch)return;const token=epoch,p=page;status('Preparing page…');$('#prevPage').disabled=p<=1;$('#nextPage').disabled=p>=doc.numPages;$('#pageNumber').value=p;try{const pdfPage=await doc.getPage(p);if(token!==epoch||job!==renderEpoch)return;const base=pdfPage.getViewport({scale:1});const available=Math.max(240,$('#pdfScroll').clientWidth-(innerWidth<700?24:48));const cssScale=available/base.width*zoom;const view=pdfPage.getViewport({scale:cssScale});const ratio=Math.min(devicePixelRatio||1,2,Math.sqrt(14000000/(view.width*view.height)));const canvas=$('#pdfCanvas');for(const l of layers.values())if(l.target===$('#pdfPage'))l.svg.remove();$('#pdfPage').style.width=view.width+'px';$('#pdfPage').style.height=view.height+'px';canvas.width=Math.floor(view.width*ratio);canvas.height=Math.floor(view.height*ratio);renderTask=pdfPage.render({canvasContext:canvas.getContext('2d'),viewport:view,transform:[ratio,0,0,ratio,0,0]});await renderTask.promise;if(token!==epoch||job!==renderEpoch)return;attach($('#pdfPage'),'pdf-'+p);status('');$('#zoomLabel').textContent=Math.round(zoom*100)+'%'}catch(e){if(e.name!=='RenderingCancelledException'&&token===epoch){status('This page could not render. Try another page.');console.error(e)}}});return renderQueue;}
function goPage(n){if(!doc)return;page=Math.max(1,Math.min(doc.numPages,Math.round(n)||1));$('#pdfScroll').scrollTo(0,0);renderPDF()}
$('#prevPage').onclick=()=>goPage(page-1);$('#nextPage').onclick=()=>goPage(page+1);$('#pageNumber').onchange=e=>goPage(+e.target.value);$('#zoomIn').onclick=()=>{zoom=Math.min(2.5,zoom+.25);renderPDF()};$('#zoomOut').onclick=()=>{zoom=Math.max(.5,zoom-.25);renderPDF()};$('#fitPage').onclick=()=>{zoom=1;renderPDF()};
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(doc)renderPDF()},180)});
function closeMaterial(show=true){epoch++;renderEpoch++;clearInterval(deckTimer);deckTimer=null;renderTask?.cancel();renderTask=null;loadingTask?.destroy().catch(()=>{});loadingTask=null;doc=null;for(const l of layers.values())l.destroy();layers.clear();active=null;current=null;page=1;zoom=1;$('#deck').onload=null;$('#deck').src='about:blank';$('#deck').hidden=true;$('#pdfScroll').hidden=true;$('#pdfControls').hidden=true;$('#viewer').hidden=true;$('#pdfCanvas').width=0;$('#pdfCanvas').height=0;if(show){$('#library').hidden=false;renderLibrary();$('#choices [data-material]')?.focus()}}
$('#closeViewer').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});closeMaterial()};
$('#fullViewer').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#viewer').requestFullscreen()}catch{$('#toolHint').textContent='For more room in Safari, hide its toolbar or add this site to your Home Screen.'}};
window.addEventListener('pagehide',()=>closeMaterial(false));
